<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>
<script>
$('.btn-choose').on('click',function(){$('#votePackageId').val(this.dataset.package);$('#chosenNumber').text(this.dataset.number);$('#chosenName').text(this.dataset.name);$('#voteModal').modal('show')});
$('#voteForm').on('submit',function(){const b=$('#submitVote');b.prop('disabled',true).html('<i class="fas fa-spinner fa-spin mr-1"></i>Mengamankan suara...')});
const c=document.getElementById('voteCountdown');if(c){const start=new Date(c.dataset.start),end=new Date(c.dataset.end);const tick=()=>{const now=new Date(),target=now<start?start:end,d=Math.max(0,target-now),days=Math.floor(d/86400000),h=Math.floor(d%86400000/3600000),m=Math.floor(d%3600000/60000);c.textContent=d<=0?'Jadwal selesai':(now<start?'Dibuka dalam ':'Berakhir dalam ')+(days?days+' hari ':'')+h+'j '+m+'m'};tick();setInterval(tick,60000)}
@if(session('error'))Swal.fire({icon:'error',title:'Suara belum tersimpan',text:@json(session('error')),confirmButtonColor:'#2563eb'});@endif
@if($errors->any())Swal.fire({icon:'error',title:'Periksa konfirmasi',text:@json($errors->first()),confirmButtonColor:'#2563eb'});@endif
</script>
@stop
